esqlQuery.esql:
TS metrics-supabase.metrics.otel-*
// pg_stat_database_num_backends is the count PostgreSQL enforces against max_connections, so
// it is the numerator. The pooler-reported counts run lower because they see only their own
// clients; they are carried for attribution.
| STATS
    `Backends` = SUM(LAST_OVER_TIME(pg_stat_database_num_backends)),
    `Max Connections` = MAX(LAST_OVER_TIME(max_connections_connection_count)),
    `Pooled Connections` = SUM(LAST_OVER_TIME(connection_stats_connection_count)),
    `Direct Connections` = MAX(LAST_OVER_TIME(direct_connection_stats_connection_count))
  BY resource.attributes.supabase_project_ref
// Guard against a missing or zero ceiling producing a divide-by-zero percentage.
| WHERE `Max Connections` > 0
| EVAL `Connection Utilisation %` = ROUND(`Backends` / `Max Connections` * 100, 1)
// 90% leaves almost no headroom before new clients are refused. Supabase guidance is to
// keep the poolers under ~40% of max_connections when the REST API is busy, so lower this
// to 70-80% if you want earlier warning.
| WHERE `Connection Utilisation %` >= 90
| SORT `Connection Utilisation %` DESC
